<?php
namespace App\Http\Controllers; use Illuminate\Http\Request; use Illuminate\Support\Facades\Auth;
class AuthController extends Controller {public function create(){return view('auth.login');}public function store(Request $request){$c=$request->validate(['email'=>['required','email'],'password'=>['required']]);if(!Auth::attempt($c,$request->boolean('remember')))return back()->withErrors(['email'=>'بيانات الدخول غير صحيحة.'])->onlyInput('email');$request->session()->regenerate();return redirect()->intended(route('sales.index'));}public function destroy(Request $request){Auth::logout();$request->session()->invalidate();$request->session()->regenerateToken();return redirect()->route('login');}}
